const existing=$input.all().map(x=>x.json||{}).filter(x=>x.candidate_id||x.claim_text);
const candidates=$('Validate Global Batch Completeness').all().map(x=>x.json||{}).filter(x=>x.candidate_id);
const existingIds=new Set(existing.map(x=>String(x.candidate_id||'')).filter(Boolean));
const existingTexts=new Set(existing.map(x=>String(x.claim_text||'')).filter(Boolean));
const pending=candidates.filter(c=>!existingIds.has(String(c.candidate_id))&&!existingTexts.has(String(c.claim_text)));
if(!pending.length){
 return [{json:{alreadySaved:true,researchRunId:$('Execute Workflow Trigger').first().json.researchRunId,newClaimCount:0,existingClaimCount:existing.length}}];
}
return pending.map(c=>({json:c}));
